import { basename, extname } from "node:path";
import matter from "gray-matter";
import {
  assertValidSourceEntries,
  buildManifest,
  buildSearchIndex,
  compileSvelteContent,
  createDiagnostic,
  createDocsError,
  createSourceEntryId,
  createDocsSearchRuntime,
  normalizeProviderPath,
  toLegacyRawEntries,
  type CompiledContentArtifact,
  type DocsCollection,
  type DocsCompatPreset,
  type DocsConfig,
  type DocsContentProvider,
  type DocsManifest,
  type DocsSearchArtifact,
  type DocsSearchRuntime,
  type DocsSourceEntry,
} from "@docsfn/core";

export interface DocsSiteSource {
  siteRoot: string;
  manifest: DocsManifest;
  searchArtifact: DocsSearchArtifact;
  siteTitle: string;
  canonicalUrl?: string;
  compatPreset: DocsCompatPreset;
  config: DocsConfig;
}

export interface DocsSiteCompiledCacheSummary {
  framework: "svelte";
  compatPreset: DocsCompatPreset;
  pageKeys: string[];
  postKeys: string[];
}

interface DocsSiteCompiledContentCache {
  framework: "svelte";
  compatPreset: DocsCompatPreset;
  pages: Map<string, CompiledContentArtifact>;
  posts: Map<string, CompiledContentArtifact>;
  pageKeysById: Record<string, string>;
  postKeysById: Record<string, string>;
}

interface DocsSiteServerState {
  source: DocsSiteSource;
  compiledCache: DocsSiteCompiledContentCache;
}

function createCompiledCacheKey(input: {
  kind: "page" | "post";
  id: string;
  framework: "svelte";
  compatPreset: DocsCompatPreset;
}): string {
  return [input.kind, input.id, input.framework, input.compatPreset].join("|");
}

function sortById<T extends { id: string }>(items: T[]): T[] {
  return [...items].sort((left, right) =>
    left.id.localeCompare(right.id, "en", {
      sensitivity: "variant",
      numeric: true,
    }),
  );
}

function createCompiledCache(input: {
  manifest: DocsManifest;
  compatPreset: DocsCompatPreset;
}): DocsSiteCompiledContentCache {
  const framework = "svelte" as const;
  const pages = new Map<string, CompiledContentArtifact>();
  const posts = new Map<string, CompiledContentArtifact>();
  const pageKeysById: Record<string, string> = {};
  const postKeysById: Record<string, string> = {};

  for (const page of sortById(Object.values(input.manifest.pages))) {
    const key = createCompiledCacheKey({
      kind: "page",
      id: page.id,
      framework,
      compatPreset: input.compatPreset,
    });
    pageKeysById[page.id] = key;
    pages.set(
      key,
      compileSvelteContent({
        source: page.body,
        sourcePath: page.id,
        compatPreset: input.compatPreset,
      }),
    );
  }

  for (const post of sortById(Object.values(input.manifest.posts))) {
    const key = createCompiledCacheKey({
      kind: "post",
      id: post.id,
      framework,
      compatPreset: input.compatPreset,
    });
    postKeysById[post.id] = key;
    posts.set(
      key,
      compileSvelteContent({
        source: post.body,
        sourcePath: post.id,
        compatPreset: input.compatPreset,
      }),
    );
  }

  return {
    framework,
    compatPreset: input.compatPreset,
    pages,
    posts,
    pageKeysById,
    postKeysById,
  };
}

function getCompiledArtifactOrThrow(input: {
  kind: "page" | "post";
  id: string;
  cache: DocsSiteCompiledContentCache;
}): CompiledContentArtifact {
  const keysById =
    input.kind === "page" ? input.cache.pageKeysById : input.cache.postKeysById;
  const entries = input.kind === "page" ? input.cache.pages : input.cache.posts;
  const key = keysById[input.id];

  if (!key) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `compiled ${input.kind} cache key is missing for ${input.id}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `compiled ${input.kind} cache key is missing for ${input.id}`,
          details: {
            kind: input.kind,
            id: input.id,
          },
        }),
      ],
    });
  }

  const compiled = entries.get(key);
  if (!compiled) {
    throw createDocsError({
      code: "DOCS_ARTIFACT_INVALID",
      message: `compiled ${input.kind} artifact is missing for ${input.id}`,
      diagnostics: [
        createDiagnostic({
          code: "DOCS_ARTIFACT_INVALID",
          message: `compiled ${input.kind} artifact is missing for ${input.id}`,
          details: {
            kind: input.kind,
            id: input.id,
            key,
          },
        }),
      ],
    });
  }

  return compiled;
}

/** One independent cache per site; raw modules are supplied by the site's Vite glob. */
export function createDocsSiteRuntime(
  docsConfig: DocsConfig,
  bundledContent: Record<string, string>,
  bundledStatic: Record<string, string>,
  modulePrefix = "../../../",
) {
  let serverStatePromise: Promise<DocsSiteServerState> | null = null;
  async function loadDocsSiteServerState(): Promise<DocsSiteServerState> {
    serverStatePromise ??= (async () => {
        const siteRoot = ".";
        const config = docsConfig satisfies DocsConfig;
        const provider = createBundledContentProvider(config);
        const manifest = await buildManifest(provider, config);
        const searchArtifact = await buildSearchIndex(manifest, {
          search: config.search,
          auth: config.auth,
        });
        const compatPreset = config.compat?.preset ?? "none";
        const compiledCache = createCompiledCache({
          manifest,
          compatPreset,
        });

        return {
          source: {
            siteRoot,
            manifest,
            searchArtifact,
            siteTitle: config.site.title,
            canonicalUrl: config.site.canonicalUrl,
            compatPreset,
            config,
          },
          compiledCache,
        };
    })().catch((error) => {
      serverStatePromise = null;
      throw error;
    });

    return serverStatePromise;
  }

  async function loadDocsSiteSource(): Promise<DocsSiteSource> {
    const state = await loadDocsSiteServerState();
    return state.source;
  }

  async function getCompiledDocsPage(
    pageId: string,
  ): Promise<CompiledContentArtifact> {
    const state = await loadDocsSiteServerState();
    return getCompiledArtifactOrThrow({
      kind: "page",
      id: pageId,
      cache: state.compiledCache,
    });
  }

  async function getCompiledDocsPost(
    postId: string,
  ): Promise<CompiledContentArtifact> {
    const state = await loadDocsSiteServerState();
    return getCompiledArtifactOrThrow({
      kind: "post",
      id: postId,
      cache: state.compiledCache,
    });
  }

  async function getDocsSiteCompiledCacheSummary(): Promise<DocsSiteCompiledCacheSummary> {
    const state = await loadDocsSiteServerState();
    return {
      framework: state.compiledCache.framework,
      compatPreset: state.compiledCache.compatPreset,
      pageKeys: [...state.compiledCache.pages.keys()].sort((left, right) =>
        left.localeCompare(right, "en", {
          sensitivity: "variant",
          numeric: true,
        }),
      ),
      postKeys: [...state.compiledCache.posts.keys()].sort((left, right) =>
        left.localeCompare(right, "en", {
          sensitivity: "variant",
          numeric: true,
        }),
      ),
    };
  }

  async function createDocsSiteSearchRuntime(): Promise<DocsSearchRuntime> {
    const state = await loadDocsSiteServerState();
    return createDocsSearchRuntime({
      artifact: state.source.searchArtifact,
    });
  }

  function createBundledContentProvider(
    config: DocsConfig,
  ): DocsContentProvider {
    const modules = {
      ...normalizeBundledModules(bundledContent, modulePrefix),
      ...normalizeBundledModules(bundledStatic, modulePrefix),
    };

    return {
      providerId: "bundled",
      async listEntries(input) {
        const entries = input.collections.flatMap((collection) =>
          collectEntriesForCollection(collection, modules, config),
        );
        return assertValidSourceEntries(entries);
      },
      async loadEntry(input) {
        return input.entry;
      },
      async list() {
        const entries = await this.listEntries({
          config,
          collections: ["docs", "pages", "blog", "api", "assets"],
        });
        return toLegacyRawEntries(entries);
      },
    };
  }

  return {
    loadDocsSiteSource,
    getCompiledDocsPage,
    getCompiledDocsPost,
    getDocsSiteCompiledCacheSummary,
    createDocsSiteSearchRuntime,
  };
}

function normalizeBundledModules(
  modules: Record<string, string>,
  prefix: string,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(modules).map(([modulePath, source]) => [
      normalizeProviderPath(modulePath.replace(prefix, "")),
      source,
    ]),
  );
}

function isMarkdownCollection(collection: DocsCollection): collection is Extract<DocsCollection, "docs" | "pages" | "blog"> {
  return ["docs", "pages", "blog"].includes(collection);
}

function collectEntriesForCollection(
  collection: DocsCollection,
  modules: Record<string, string>,
  config: DocsConfig,
): DocsSourceEntry[] {
  const directory = collectionDirectory(collection, config);
  const entries: DocsSourceEntry[] = [];

  for (const [modulePath, source] of Object.entries(modules)) {
    if (modulePath !== directory && !modulePath.startsWith(`${directory}/`)) {
      continue;
    }

    const relativePath = normalizeProviderPath(
      modulePath.slice(directory.length + 1),
    );
    if (!relativePath || relativePath === ".gitkeep") {
      continue;
    }

    const extension = extname(relativePath).toLowerCase();
    const fileName = basename(relativePath).toLowerCase();

    if (fileName === (config.content.metaFileName ?? "meta.json").toLowerCase()) {
      entries.push(createControlEntry(collection, relativePath, source, modulePath));
      continue;
    }

    if (collection === "assets") {
      entries.push(createAssetEntry(relativePath, source, modulePath));
      continue;
    }

    if (
      isMarkdownCollection(collection) &&
      [".md", ".mdx"].includes(extension)
    ) {
      entries.push(createMarkdownEntry(collection, relativePath, source, modulePath));
      continue;
    }

    if (
      collection === "api" &&
      [".json", ".yaml", ".yml"].includes(extension)
    ) {
      entries.push(createApiEntry(relativePath, source, modulePath));
    }
  }

  return entries.sort((left, right) =>
    left.id.localeCompare(right.id, "en", {
      sensitivity: "variant",
      numeric: true,
    }),
  );
}

function collectionDirectory(
  collection: DocsCollection,
  config: DocsConfig,
): string {
  if (collection === "docs") return config.content.docsDir ?? "content/docs";
  if (collection === "pages") return config.content.pagesDir ?? "content/pages";
  if (collection === "blog") return config.content.blogDir ?? "content/blog";
  if (collection === "api") return config.content.apiDir ?? "content/api";
  return config.content.assetsDir ?? "static";
}

function createMarkdownEntry(
  collection: Extract<DocsCollection, "docs" | "pages" | "blog">,
  relativePath: string,
  source: string,
  sourcePath: string,
): DocsSourceEntry {
  const parsed = parseFrontmatter(source);
  return {
    id: createSourceEntryId(collection, relativePath),
    collection,
    relativePath,
    absolutePath: sourcePath,
    entryType: "content",
    body: parsed.body,
    frontmatter: {
      title: deriveTitleFromPath(relativePath),
      ...parsed.frontmatter,
    },
    bytes: byteLength(source),
    meta: {
      extension: extname(relativePath).toLowerCase(),
    },
  };
}

function createControlEntry(
  collection: DocsCollection,
  relativePath: string,
  source: string,
  sourcePath: string,
): DocsSourceEntry {
  return {
    id: createSourceEntryId(collection, relativePath),
    collection,
    relativePath,
    absolutePath: sourcePath,
    entryType: "control",
    body: source,
    frontmatter: {},
    bytes: byteLength(source),
    meta: {
      controlFile: true,
      parsed: parseJson(source),
    },
  };
}

function createApiEntry(relativePath: string, source: string, sourcePath: string): DocsSourceEntry {
  return {
    id: createSourceEntryId("api", relativePath),
    collection: "api",
    relativePath,
    absolutePath: sourcePath,
    entryType: "content",
    body: source,
    frontmatter: {
      title: deriveTitleFromPath(relativePath),
    },
    bytes: byteLength(source),
    meta: {
      extension: extname(relativePath).toLowerCase(),
    },
  };
}

function createAssetEntry(
  relativePath: string,
  source: string,
  sourcePath: string,
): DocsSourceEntry {
  return {
    id: createSourceEntryId("assets", relativePath),
    collection: "assets",
    relativePath,
    absolutePath: sourcePath,
    entryType: "asset",
    frontmatter: {},
    bytes: byteLength(source),
  };
}

function parseFrontmatter(source: string): {
  body: string;
  frontmatter: Record<string, unknown>;
} {
  const parsed = matter(source);
  return { body: parsed.content, frontmatter: parsed.data };
}

function parseJson(source: string): unknown {
  try {
    return JSON.parse(source);
  } catch {
    return null;
  }
}

function deriveTitleFromPath(relativePath: string): string {
  return basename(relativePath)
    .replace(/\.[^/.]+$/, "")
    .split(/[-_]/g)
    .map((segment) =>
      segment.length > 0
        ? `${segment.charAt(0).toUpperCase()}${segment.slice(1)}`
        : segment,
    )
    .join(" ");
}

function byteLength(source: string): number {
  return new TextEncoder().encode(source).byteLength;
}

import { error } from "@sveltejs/kit";
import {
  getTopNavigation,
  type CompiledContentArtifact,
  type Sidebar,
} from "@docsfn/core";
import {
  resolveDocsPageSurface,
  resolveDocsRouteDataOrThrow,
  type SvelteDocsPageSurface,
} from "@docsfn/sveltekit";
import type { DocsSiteSource } from "./runtime";

interface DocsPageOptions {
  apiBreadcrumbLabel?: string;
  apiBreadcrumbHref?: string;
  fallbackSidebarId?: string;
}

function buildCanonicalUrl(canonicalBase: string | undefined, path: string): string {
  if (!canonicalBase) return path;
  const origin = canonicalBase.replace(/\/+$/, "");
  return `${origin}${path.startsWith("/") ? path : `/${path}`}`;
}

function isRouteNotFoundError(input: unknown): input is { message: string } {
  return (
    typeof input === "object" && input !== null &&
    "code" in input && input.code === "DOCS_ROUTE_NOT_FOUND" &&
    "message" in input && typeof input.message === "string"
  );
}

function hasNestedDocsRoutes(routes: Record<string, string>, route: string): boolean {
  return Object.keys(routes).some((candidate) => candidate.startsWith(`${route}/`));
}

export async function loadDocsPage(input: {
  slug: string | undefined;
  source: DocsSiteSource;
  getCompiledDocsPage: (id: string) => Promise<CompiledContentArtifact>;
  resolveMarkdownRelativeLinks: (input: {
    compiled: CompiledContentArtifact;
    route: string;
    sourcePath: string;
    isIndexRoute: boolean;
  }) => CompiledContentArtifact;
  options?: DocsPageOptions;
}) {
  const { slug, source, getCompiledDocsPage, resolveMarkdownRelativeLinks, options = {} } = input;
  let routeEntry;
  try {
    routeEntry = resolveDocsRouteDataOrThrow(slug, source.manifest, { basePath: "/docs" });
  } catch (routeError) {
    if (isRouteNotFoundError(routeError)) throw error(404, routeError.message);
    throw routeError;
  }

  if (routeEntry.kind === "post") {
    throw error(404, `unsupported docs route kind: ${routeEntry.kind}`);
  }

  let surface: SvelteDocsPageSurface;
  if (routeEntry.kind === "api") {
    const api = routeEntry.api;
    const route = routeEntry.route;
    surface = {
      route,
      title: api.title,
      description: typeof api.frontmatter.description === "string" ? api.frontmatter.description : undefined,
      canonicalPath: route,
      canonicalUrl: buildCanonicalUrl(source.canonicalUrl, route),
      sidebarId: "api",
      headings: [],
      breadcrumbs: [
        { label: "Docs", href: "/docs" },
        { label: options.apiBreadcrumbLabel ?? "API Reference", href: options.apiBreadcrumbHref ?? "/docs/api" },
        { label: api.title, href: route },
      ],
      pagination: {},
      topNav: getTopNavigation(source.manifest),
      versions: source.manifest.versions,
    };
  } else {
    surface = resolveDocsPageSurface({
      manifest: source.manifest,
      route: routeEntry.route,
      page: routeEntry.page,
      options: {
        basePath: "/docs",
        homeHref: "/docs",
        canonicalUrl: source.canonicalUrl,
        versionMode: "path-prefix",
      },
    });
  }

  const sidebarId = surface.sidebarId ?? "default";
  const sidebar: Sidebar | undefined = source.manifest.sidebars[sidebarId] ??
    (options.fallbackSidebarId ? source.manifest.sidebars[options.fallbackSidebarId] : undefined);
  const compiled = routeEntry.kind === "page"
    ? resolveMarkdownRelativeLinks({
        compiled: await getCompiledDocsPage(routeEntry.page.id),
        route: routeEntry.route,
        sourcePath: routeEntry.page.id.replace(/^docs:/, ""),
        isIndexRoute: hasNestedDocsRoutes(source.manifest.routes, routeEntry.route),
      })
    : undefined;

  return {
    routeEntry,
    surface,
    sidebar,
    compiled,
    searchDocumentCount: Array.isArray(source.searchArtifact.documents) ? source.searchArtifact.documents.length : 0,
    searchScopes: Array.isArray(source.searchArtifact.scopes) ? source.searchArtifact.scopes.join(", ") : "none",
    siteTitle: source.siteTitle,
    compatPreset: source.compatPreset,
  };
}

import path from "node:path";
import { createRequire } from "node:module";
import type { Plugin } from "vite";

/** Resolve shared source with its consuming site's pin, preserving dependency-owned imports. */
export function docsSiteCorePlugin(configUrl: string): Plugin {
  const require = createRequire(configUrl);
  const directory = path.dirname(require.resolve("@docsfn/core"));
  return {
    name: "docs-site-pinned-core",
    enforce: "pre",
    resolveId(source, importer) {
      if (!importer?.replaceAll("\\", "/").includes("/scripts/docs-site/")) return;
      if (source === "@docsfn/core") return path.join(directory, "index.js");
      if (source === "@docsfn/core/search-runtime") return path.join(directory, "search-runtime.js");
    },
  };
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");

export const docsProducts = {
  sendfn: {
    packageName: "@sendfn/docs",
    docsDir: "sendfn/docs",
    kind: "sveltekit-cloudflare",
    zoneName: "sendfn.com",
    hosts: { dev: "dev.sendfn.com", live: "sendfn.com" },
  },
  datafn: {
    packageName: "@datafn/docs",
    docsDir: "datafn/docs",
    kind: "next-static",
    zoneName: "datafn.dev",
    hosts: {
      dev: "dev.datafn.dev",
      live: "datafn.dev",
    },
    routeAliases: {
      live: ["www.datafn.dev"],
    },
  },
  filefn: {
    packageName: "@filefn/docs",
    docsDir: "filefn/docs",
    kind: "sveltekit-cloudflare",
    zoneName: "filefn.com",
    hosts: {
      dev: "dev.filefn.com",
      live: "filefn.com",
    },
  },
  searchfn: {
    packageName: "@searchfn/docs",
    docsDir: "searchfn/docs",
    kind: "next-static",
    zoneName: "searchfn.com",
    hosts: {
      dev: "dev.searchfn.com",
      live: "searchfn.com",
    },
    routeAliases: {
      live: ["www.searchfn.com"],
    },
  },
  authfn: {
    packageName: "@authfn/docs",
    docsDir: "authfn/docs",
    kind: "sveltekit-cloudflare",
    zoneName: "authfn.com",
    hosts: {
      dev: "dev.authfn.com",
      live: "authfn.com",
    },
  },
};

export const environments = ["dev", "live"];

export function normalizeEnvironment(value) {
  const normalized = String(value ?? "").trim().toLowerCase();
  return environments.includes(normalized) ? normalized : null;
}

export function productIds() {
  return Object.keys(docsProducts);
}

export function existingProductIds() {
  return productIds().filter((productId) => hasDocsPackage(productId));
}

export function parseProducts(value, { existingOnly = false } = {}) {
  const raw = String(value ?? "all").trim();
  const available = existingOnly ? existingProductIds() : productIds();
  if (raw === "all") return available;

  const selected = raw.split(",").map((entry) => entry.trim()).filter(Boolean);
  if (selected.length === 0) {
    throw new Error("At least one docs product is required.");
  }

  for (const productId of selected) {
    if (!docsProducts[productId]) {
      throw new Error(`Invalid docs product: ${productId}`);
    }
    if (existingOnly && !hasDocsPackage(productId)) {
      throw new Error(`Docs package is missing for ${productId}: ${docsProducts[productId].docsDir}/package.json`);
    }
  }

  return [...new Set(selected)];
}

export function hasDocsPackage(productId) {
  return fs.existsSync(path.join(repoRoot, docsProducts[productId].docsDir, "package.json"));
}

export function workerName(productId, environment) {
  return `superfunctions-${productId}-docs-${environment}`;
}

export function routeDefinition(productId, environment) {
  const product = docsProducts[productId];
  return {
    product: productId,
    zoneName: product.zoneName,
    pattern: `${product.hosts[environment]}/docs*`,
    script: workerName(productId, environment),
  };
}

export function routesFor(environment, products) {
  return products.flatMap((productId) => {
    const route = routeDefinition(productId, environment);
    const product = docsProducts[productId];
    const aliases = product.routeAliases?.[environment] ?? [];
    return [
      route,
      ...aliases.map((host) => ({
        ...route,
        pattern: `${host}/docs*`,
      })),
    ];
  });
}

export function jsonArray(values) {
  return JSON.stringify([...new Set(values)]);
}

# Sendfn TypeScript SDK

The `sendfn` SDK is a unified communications platform that provides email, SMS, WhatsApp, and push notification capabilities. It follows the Superfunctions pattern, utilizing shared database and HTTP abstractions with a modular adapter system for providers.

## Features

- **Unified API**: Send emails, SMS, WhatsApp messages, and push notifications through a single interface.
- **Adapter-Based Providers**: Inject your preferred providers (for example AWS SES for email, Meta WhatsApp Cloud API for WhatsApp, APNS/FCM for push, and the shipped console SMS adapter for development).
- **Built-in API Router**: Optional REST API endpoints for remote management.
- **Template Engine**: Lightweight engine with default templates (Welcome, Password Reset, etc.).
- **Suppression Management**: Built-in handling for email bounces and complaints.
- **Database Agnostic**: Uses `@superfunctions/db` adapters (Drizzle, Prisma, Kysely, etc.).

## Installation

```bash
npm install sendfn @superfunctions/db @superfunctions/http@0.1.2 @superfunctions/http-express@0.1.2 express
```

## Verify From Repo Root

```bash
npm install
npm run build --workspace sendfn/typescript
npm run lint --workspace sendfn/typescript
npm test --workspace sendfn/typescript -- --run
```

Inside the package itself you can also run:

```bash
npm run release:verify
```

## Quick Start

### 1. Initialize the Client

```typescript
import { sendfn, awsSesAdapter, consoleSmsAdapter } from 'sendfn';
import { apnsAdapter } from 'sendfn/adapters/apns';
import { metaWhatsAppAdapter } from 'sendfn/adapters/meta-whatsapp';
import type { Adapter } from '@superfunctions/db';

// 1. Setup your shared database adapter.
// Replace this placeholder with drizzle/prisma/kysely/etc from @superfunctions/db.
const database = {} as Adapter;

const whatsappAccessToken = process.env.WHATSAPP_ACCESS_TOKEN;
const whatsappPhoneNumberId = process.env.WHATSAPP_PHONE_NUMBER_ID;

if (!whatsappAccessToken || !whatsappPhoneNumberId) {
  throw new Error(
    'WHATSAPP_ACCESS_TOKEN and WHATSAPP_PHONE_NUMBER_ID are required',
  );
}

// 2. Initialize sendfn with desired providers
const client = sendfn({
  database,
  emailProvider: awsSesAdapter({
    accessKeyId: process.env.AWS_ACCESS_KEY_ID!,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY!,
    region: 'us-east-1',
  }),
  smsProvider: consoleSmsAdapter(), // Logs SMS to console for development
  whatsappProvider: metaWhatsAppAdapter({
    accessToken: whatsappAccessToken,
    phoneNumberId: whatsappPhoneNumberId,
  }),
  pushProviders: {
    ios: apnsAdapter({
      keyId: process.env.APNS_KEY_ID!,
      teamId: process.env.APNS_TEAM_ID!,
      key: process.env.APNS_PRIVATE_KEY!,
      bundleId: 'com.example.app',
      production: false,
    }),
  },
  email: {
    fromEmail: 'noreply@yourdomain.com',
    fromName: 'SuperFunctions App',
  },
  enableApi: true,
  apiConfig: {
    adminKey: process.env.SENDFN_ADMIN_KEY,
  },
});
```

### 2. Use the API Router

If `enableApi` is true, the `client.router` instance is available to be mounted on any supported framework via Superfunctions HTTP adapters.

```typescript
import express from 'express';
import { toExpress } from '@superfunctions/http-express';

const app = express();
app.use(express.raw({ type: '*/*', limit: '2mb' }));
if (!client.router) throw new Error('Set enableApi: true before mounting');
app.use(toExpress(client.router));
app.listen(3000);

// Admin endpoints require 'Authorization: Bearer <adminKey>'.
// The SNS webhook is an exception: it verifies the SNS signature and topic ARN.
// POST /email - Send an email
// POST /sms   - Send an SMS
// POST /whatsapp - Send a WhatsApp message
// POST /push             - Send a push notification
// POST /devices          - Register a native/web device token
// GET  /devices          - List active device tokens for a user
// POST /devices/refresh  - Refresh a native/web device token
// DELETE /devices        - Deactivate a device token
// GET  /events           - Query communication events
// POST /webhooks/aws-ses - Present only when awsSns.topicArns is configured
```

## Configuration

```typescript
interface SendfnConfig {
  database: Adapter;           // From @superfunctions/db
  emailProvider?: EmailProvider; // e.g., awsSesAdapter()
  smsProvider?: SmsProvider;     // e.g., consoleSmsAdapter()
  whatsappProvider?: WhatsAppProvider; // e.g., metaWhatsAppAdapter()
  email?: EmailConfig;         // Default settings (fromEmail, fromName)
  pushProviders?: Partial<Record<Platform, PushProvider>>; // APNS/FCM/custom adapters
  push?: PushConfig;           // Legacy credentials for FCM/APNS
  options?: {
    suppressionEnabled?: boolean; // default: true
    eventTracking?: boolean;      // default: true
  };
  enableApi?: boolean;            // default: false
  apiConfig?: {
    adminKey?: string;           // Required if enableApi is true
  };
}
```

## Usage Guide

### Sending Email

```typescript
await client.email({
  userId: 'user-123',
  to: 'user@example.com',
  subject: 'Hello',
  html: '<strong>Welcome to Superfunctions!</strong>',
});
```

### Sending SMS

```typescript
await client.sms({
  userId: 'user-123',
  to: '+1234567890',
  message: 'Your verification code is 554433',
});
```

### Sending WhatsApp Messages

```typescript
await client.whatsapp({
  userId: 'user-123',
  to: '+1234567890',
  message: 'Your reminder is due',
});
```

### Sending Push Notifications

```typescript
// Register a device token for a user
await client.registerDevice({
  userId: 'user-123',
  token: 'apns-token-xyz',
  platform: 'ios',
});

// Send push to all active devices of the user
await client.push({
  userId: 'user-123',
  title: 'Alert',
  body: 'Something happened!',
});
```

### AWS SES Webhooks

To handle bounces and complaints automatically, authorize every SNS topic that may deliver SES lifecycle events when constructing the client. SendFn does not expose the handler or built-in route with an empty allowlist.

```typescript
const client = sendfn({
  database,
  awsSns: {
    topicArns: ['arn:aws:sns:us-east-1:123456789012:sendfn-production'],
  },
});
```

For an HTTP host, include this `awsSns` option in the client configured with
`enableApi: true` above and mount `client.router` using the API-router example.
Its built-in `POST /webhooks/aws-ses` route parses the raw JSON body and verifies
the complete SNS envelope before mutating delivery, bounce, or complaint state.
Do not register a second Express handler that passes the `express.raw()` Buffer
directly to `handleSnsNotification`, which expects an SNS message object.

For a custom host calling `handleSnsNotification` directly, JSON-decode the bytes
and preserve every SNS envelope field, including `Signature`, `SigningCertURL`,
`Timestamp`, and `Message`; do not pass only the inner SES message.

